    blurb: "Too many reds at the start. Blue dips first, red fades later.",
    params: {
      redStart: 45,
    },
  },
  {
    id: "fragile",
    name: "Fragile balance",
    blurb: "Few trees to hide under, sharp-eyed reds. Big swings, near misses.",
    params: {
      trees: 10,
