            schedule();
          }}
          onPointerLeave={() => {
            hover.current = null;
            schedule();
          }}
        />
      </div>
      <div className="legend">
        {SERIES.map((sr) => (
          <button
            key={sr.key}
            className={`legend-item ${hidden[sr.key] ? "is-off" : ""}`}
            onClick={() => setHidden((h) => ({ ...h, [sr.key]: !h[sr.key] }))}
            aria-pressed={!hidden[sr.key]}
          >
            <i style={{ background: sr.color }} />
            {sr.label}
            <b>{now[sr.key]}</b>
          </button>
        ))}
      </div>
    </section>
  );
}

