import { chromium } from "playwright";

const browser = await chromium.launch({ channel: "chromium", args: ["--ignore-gpu-blocklist"] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
await page.goto("http://127.0.0.1:9348/", { waitUntil: "load" });
await page.waitForTimeout(1200);
await page.evaluate(`(() => {
  const c = window.__garden;
  for (let i = 0; i < 20 * 70; i++) c.stepOnce();
  c.drainEvents();
  c.setParam("simSpeed", 1);
  c.play();
})()`);
await page.waitForTimeout(800);
for (const [i, want] of [["a", "rest"], ["b", "wait"], ["c", "hide"], ["d", "chase"]] as const) {
  const found = await page.evaluate(`(() => {
    const c = window.__garden; const r = window.__gardenRenderer;
    const b = c.world.blobs.find((x) => x.action === "${want}" && (x.action !== "hide" || x.sheltered));
    if (!b) return null;
    c.select(b.id);
    r.controls.target.set(b.x, 0.4, b.y);
    r.camera.position.set(b.x + 2.2, 2.4, b.y + 3.2);
    r.home.set(b.x, 0.4, b.y);
    r.controls.update();
    return b.name + " " + b.action;
  })()`);
  await page.waitForTimeout(700);
  console.log(i, want, found);
  if (found) await page.locator(".garden-card").screenshot({ path: `.prof/close-${i}-${want}.png` });
}
await browser.close();
